 89	import com.pousadamarealta.dto.MessageResponse;
 90	import com.pousadamarealta.model.Message;
 91	import com.pousadamarealta.repository.MessageRepository;
 92	import io.javalin.http.Context;
 93	
 94	import java.util.List;
 95	import java.util.stream.Collectors;
 96	
 97	public class MessageController {
 98	    private final MessageRepository messageRepository;
 99	
100	    public MessageController(MessageRepository messageRepository) {
101	        this.messageRepository = messageRepository;
102	    }
103	
104	    public void getMessages(Context ctx) {
105	        List<MessageResponse> messages = messageRepository.findAll().stream()
106	            .map(this::toResponse)
107	            .collect(Collectors.toList());
108	
109	        ctx.json(messages);
110	    }
111	
112	    private MessageResponse toResponse(Message message) {
113	        return new MessageResponse(
114	            message.getId(),
115	            message.getChannel(),
116	            message.getTo(),
117	            message.getSubject(),
118	            message.getBody()
119	        );
120	    }
121	}
122	package com.pousadamarealta.controller;
123	
124	import com.pousadamarealta.exception.ApiException;
125	import com.pousadamarealta.service.ReportService;
126	import io.javalin.http.Context;
127	
128	import java.time.LocalDate;
129	import java.time.YearMonth;
130	import java.time.format.DateTimeFormatter;
131	import java.time.format.DateTimeParseException;
132	
133	public class ReportController {
134	    private static final DateTimeFormatter DATE_FORMAT = DateTimeFormatter.ofPattern("yyyy-MM-dd");
135	    private static final DateTimeFormatter MONTH_FORMAT = DateTimeFormatter.ofPattern("yyyy-MM");
136	
137	    private final ReportService reportService;
138	
139	    public ReportController(ReportService reportService) {
140	        this.reportService = reportService;
141	    }
142	
143	    public void getOccupancyReport(Context ctx) {
144	        String dateParam = ctx.queryParam("date");
145	        if (dateParam == null || dateParam.isEmpty()) {
146	            throw new ApiException(400, "INVALID_REQUEST", "Date parameter is required");
147	        }
148	
149	        LocalDate date = parseDate(dateParam);
150	        String csv = reportService.generateOccupancyReport(date);
151	
152	        ctx.contentType("text/csv; charset=utf-8").result(csv);
153	    }
154	
155	    public void getRevenueReport(Context ctx) {
156	        String monthParam = ctx.queryParam("month");
157	        if (monthParam == null || monthParam.isEmpty()) {
158	            throw new ApiException(400, "INVALID_REQUEST", "Month parameter is required");
159	        }
160	
161	        YearMonth yearMonth = parseMonth(monthParam);
162	        String csv = reportService.generateRevenueReport(yearMonth.getYear(), yearMonth.getMonthValue());
163	
164	        ctx.contentType("text/csv; charset=utf-8").result(csv);
165	    }
166	
167	    private LocalDate parseDate(String date) {
168	        try {
169	            return LocalDate.parse(date, DATE_FORMAT);
170	        } catch (DateTimeParseException e) {
171	            throw new ApiException(400, "INVALID_REQUEST", "Invalid date format. Expected: yyyy-MM-dd");
172	        }
173	    }
174	
175	    private YearMonth parseMonth(String month) {
176	        try {
177	            return YearMonth.parse(month, MONTH_FORMAT);
178	        } catch (DateTimeParseException e) {
179	            throw new ApiException(400, "INVALID_REQUEST", "Invalid month format. Expected: yyyy-MM");
180	        }
181	    }
182	}
183	package com.pousadamarealta.controller;
184	
185	import com.pousadamarealta.dto.CreateReservationRequest;
186	import com.pousadamarealta.dto.DocumentResponse;
187	import com.pousadamarealta.dto.ReservationResponse;
188	import com.pousadamarealta.exception.ApiException;
189	import com.pousadamarealta.model.RatePlan;
190	import com.pousadamarealta.model.Reservation;
191	import com.pousadamarealta.model.Room;
192	import com.pousadamarealta.repository.RoomRepository;
193	import com.pousadamarealta.service.ReservationService;
194	import io.javalin.http.Context;
195	
196	import java.time.LocalDate;
197	import java.time.format.DateTimeFormatter;
198	import java.time.format.DateTimeParseException;
199	
200	public class ReservationController {
201	    private static final DateTimeFormatter DATE_FORMAT = DateTimeFormatter.ofPattern("yyyy-MM-dd");
202	
203	    private final ReservationService reservationService;
204	    private final RoomRepository roomRepository;
205	
206	    public ReservationController(ReservationService reservationService, RoomRepository roomRepository) {
207	        this.reservationService = reservationService;
208	        this.roomRepository = roomRepository;
209	    }
210	
211	    public void createReservation(Context ctx) {
212	        CreateReservationRequest request = ctx.bodyAsClass(CreateReservationRequest.class);
213	
214	        validateRequest(request);
215	
216	        Reservation reservation = new Reservation();
217	        reservation.setRoomNumber(request.roomNumber());
218	        reservation.setGuestName(request.guestName());
219	        reservation.setGuestEmail(request.guestEmail());
220	        reservation.setGuestCpf(request.guestCpf());
221	        reservation.setCheckIn(parseDate(request.checkIn()));
222	        reservation.setCheckOut(parseDate(request.checkOut()));
223	        reservation.setGuests(request.guests());
224	        reservation.setRatePlan(parseRatePlan(request.ratePlan()));
225	        reservation.setCompanyCode(request.companyCode());
226	
227	        Reservation created = reservationService.createReservation(reservation);
228	
229	        ctx.status(201).json(toResponse(created));
230	    }
231	
232	    public void getReservation(Context ctx) {
233	        Long id = parseId(ctx.pathParam("id"));
234	        Reservation reservation = reservationService.getReservation(id);
235	        ctx.json(toResponse(reservation));
236	    }
237	
238	    public void confirmReservation(Context ctx) {
239	        Long id = parseId(ctx.pathParam("id"));
240	        Reservation reservation = reservationService.confirmReservation(id);
241	        ctx.json(toResponse(reservation));
242	    }
243	
244	    public void cancelReservation(Context ctx) {
245	        Long id = parseId(ctx.pathParam("id"));
246	        Reservation reservation = reservationService.cancelReservation(id);
247	        ctx.json(toResponse(reservation));
248	    }
249	
250	    public void checkIn(Context ctx) {
251	        Long id = parseId(ctx.pathParam("id"));
252	        Reservation reservation = reservationService.checkIn(id);
253	        ctx.json(toResponse(reservation));
254	    }
255	
256	    public void checkOut(Context ctx) {
257	        Long id = parseId(ctx.pathParam("id"));
258	        Reservation reservation = reservationService.checkOut(id);
259	        Room room = roomRepository.findByNumber(reservation.getRoomNumber()).orElseThrow();
260	        ctx.json(toDocumentResponse(reservation, room.getType().name()));
261	    }
262	
263	    public void getDocument(Context ctx) {
264	        Long id = parseId(ctx.pathParam("id"));
265	        Reservation reservation = reservationService.getReservation(id);
266	
267	        if (reservation.getAmountPaid().compareTo(java.math.BigDecimal.ZERO) == 0) {
268	            throw new ApiException(409, "OPERATION_NOT_ALLOWED", "Document is only available for paid reservations");
269	        }
270	
271	        Room room = roomRepository.findByNumber(reservation.getRoomNumber()).orElseThrow();
272	        ctx.json(toDocumentResponse(reservation, room.getType().name()));
273	    }
274	
275	    private void validateRequest(CreateReservationRequest request) {
276	        if (request.roomNumber() == null || request.guestName() == null ||
277	            request.guestEmail() == null || request.guestCpf() == null ||
278	            request.checkIn() == null || request.checkOut() == null ||
279	            request.ratePlan() == null) {
280	            throw new ApiException(400, "INVALID_REQUEST", "Missing required fields");
281	        }
282	    }
283	
284	    private LocalDate parseDate(String date) {
285	        try {
286	            return LocalDate.parse(date, DATE_FORMAT);
287	        } catch (DateTimeParseException e) {
288	            throw new ApiException(400, "INVALID_REQUEST", "Invalid date format. Expected: yyyy-MM-dd");
289	        }
290	    }
291	
292	    private RatePlan parseRatePlan(String ratePlan) {
293	        try {
294	            return RatePlan.valueOf(ratePlan);
295	        } catch (IllegalArgumentException e) {
296	            throw new ApiException(400, "INVALID_REQUEST", "Invalid rate plan: " + ratePlan);
297	        }
298	    }
299	
300	    private Long parseId(String id) {
301	        try {
302	            return Long.parseLong(id);
303	        } catch (NumberFormatException e) {
304	            throw new ApiException(400, "INVALID_REQUEST", "Invalid reservation ID");
305	        }
306	    }
307	
308	    private ReservationResponse toResponse(Reservation reservation) {
309	        return new ReservationResponse(
310	            reservation.getId(),
311	            reservation.getRoomNumber(),
312	            reservation.getGuestName(),
313	            reservation.getGuestEmail(),
314	            reservation.getGuestCpf(),
315	            reservation.getCheckIn().format(DATE_FORMAT),
316	            reservation.getCheckOut().format(DATE_FORMAT),
317	            reservation.getGuests(),
318	            reservation.getRatePlan().name(),
319	            reservation.getNights(),
320	            reservation.getSubtotal(),
321	            reservation.getDiscount(),
322	            reservation.getTotal(),
323	            reservation.getStatus().name(),
324	            reservation.getAmountPaid(),
325	            reservation.getRefund()
326	        );
327	    }
328	
329	    private DocumentResponse toDocumentResponse(Reservation reservation, String roomType) {
330	        return new DocumentResponse(
331	            "Comprovante de reserva",
332	            reservation.getId(),
333	            reservation.getGuestName(),
334	            reservation.getGuestCpf(),
335	            reservation.getRoomNumber(),
336	            roomType,
337	            reservation.getCheckIn().format(DATE_FORMAT),
338	            reservation.getCheckOut().format(DATE_FORMAT),
339	            reservation.getNights(),
340	            reservation.getSubtotal(),
341	            reservation.getDiscount(),
342	            reservation.getTotal()
343	        );
344	    }
345	}
