350	import com.pousadamarealta.repository.RoomRepository;
351	import io.javalin.http.Context;
352	
353	import java.util.List;
354	import java.util.stream.Collectors;
355	
356	public class RoomController {
357	    private final RoomRepository roomRepository;
358	
359	    public RoomController(RoomRepository roomRepository) {
360	        this.roomRepository = roomRepository;
361	    }
362	
363	    public void getRooms(Context ctx) {
364	        List<RoomResponse> rooms = roomRepository.findAll().stream()
365	            .map(this::toResponse)
366	            .collect(Collectors.toList());
367	
368	        ctx.json(rooms);
369	    }
370	
371	    private RoomResponse toResponse(Room room) {
372	        return new RoomResponse(
373	            room.getNumber(),
374	            room.getType().name(),
375	            room.getCapacity(),
376	            room.getNightlyRate()
377	        );
378	    }
379	}

