 19	public class Application {
 20	    public static void main(String[] args) {
 21	        String dbUrl = System.getenv().getOrDefault("DB_URL", "jdbc:postgresql://localhost:5432/pousada");
 22	        String dbUser = System.getenv().getOrDefault("DB_USER", "postgres");
 23	        String dbPassword = System.getenv().getOrDefault("DB_PASSWORD", "postgres");
 24	        String portStr = System.getenv().getOrDefault("PORT", "7070");
 25	        int port = Integer.parseInt(portStr);
 26	
 27	        Database database = new Database(dbUrl, dbUser, dbPassword);
 28	        database.initialize();
 29	
 30	        RoomRepository roomRepository = new RoomRepository();
 31	        ReservationRepository reservationRepository = new ReservationRepository(database);
 32	        MessageRepository messageRepository = new MessageRepository(database);
 33	
 34	        PricingService pricingService = new PricingService();
 35	        RatePlanFactory ratePlanFactory = new RatePlanFactory(pricingService);
 36	        NotificationService notificationService = new NotificationService(messageRepository);
 37	        ReservationService reservationService = new ReservationService(
 38	            reservationRepository, roomRepository, ratePlanFactory, notificationService, pricingService
 39	        );
 40	        ReportService reportService = new ReportService(reservationRepository, roomRepository);
 41	
 42	        RoomController roomController = new RoomController(roomRepository);
 43	        ReservationController reservationController = new ReservationController(reservationService, roomRepository);
 44	        MessageController messageController = new MessageController(messageRepository);
 45	        ReportController reportController = new ReportController(reportService);
 46	
 47	        ObjectMapper objectMapper = new ObjectMapper();
 48	        objectMapper.registerModule(new JavaTimeModule());
 49	        objectMapper.disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);
 50	
 51	        Javalin app = Javalin.create(config -> {
 52	            config.jsonMapper(new JavalinJackson(objectMapper, true));
 53	        });
 54	
 55	        app.exception(ApiException.class, Application::handleApiException);
 56	        app.exception(Exception.class, Application::handleGenericException);
 57	
 58	        app.get("/rooms", roomController::getRooms);
 59	        app.post("/reservations", reservationController::createReservation);
 60	        app.get("/reservations/{id}", reservationController::getReservation);
 61	        app.post("/reservations/{id}/confirmation", reservationController::confirmReservation);
 62	        app.post("/reservations/{id}/cancellation", reservationController::cancelReservation);
 63	        app.post("/reservations/{id}/check-in", reservationController::checkIn);
 64	        app.post("/reservations/{id}/check-out", reservationController::checkOut);
 65	        app.get("/reservations/{id}/document", reservationController::getDocument);
 66	        app.get("/messages", messageController::getMessages);
 67	        app.get("/reports/occupancy", reportController::getOccupancyReport);
 68	        app.get("/reports/revenue", reportController::getRevenueReport);
 69	
 70	        app.start(port);
 71	
 72	        System.out.println("Pousada Maré Alta - Sistema de Reservas");
 73	        System.out.println("Server started on port " + port);
 74	    }
