143	    public void getOccupancyReport(Context ctx) {
144	        String dateParam = ctx.queryParam("date");
145	        if (dateParam == null || dateParam.isEmpty()) {
146	            throw new ApiException(400, "INVALID_REQUEST", "Date parameter is required");
147	        }
