202	
203	    private final ReservationService reservationService;
204	    private final RoomRepository roomRepository;
205	
206	    public ReservationController(ReservationService reservationService, RoomRepository roomRepository) {
207	        this.reservationService = reservationService;
208	        this.roomRepository = roomRepository;
209	    }
210	
211	    public void createReservation(Context ctx) {
212	        CreateReservationRequest request = ctx.bodyAsClass(CreateReservationRequest.class);
213	
214	        validateRequest(request);
215	
216	        Reservation reservation = new Reservation();
217	        reservation.setRoomNumber(request.roomNumber());
218	        reservation.setGuestName(request.guestName());
219	        reservation.setGuestEmail(request.guestEmail());
220	        reservation.setGuestCpf(request.guestCpf());
221	        reservation.setCheckIn(parseDate(request.checkIn()));
222	        reservation.setCheckOut(parseDate(request.checkOut()));
223	        reservation.setGuests(request.guests());
224	        reservation.setRatePlan(parseRatePlan(request.ratePlan()));
225	        reservation.setCompanyCode(request.companyCode());
226	
227	        Reservation created = reservationService.createReservation(reservation);
228	
229	        ctx.status(201).json(toResponse(created));
230	    }
