241	        ctx.json(toResponse(reservation));
242	    }
243	
244	    public void cancelReservation(Context ctx) {
245	        Long id = parseId(ctx.pathParam("id"));
246	        Reservation reservation = reservationService.cancelReservation(id);
247	        ctx.json(toResponse(reservation));
248	    }
249	
250	    public void checkIn(Context ctx) {
251	        Long id = parseId(ctx.pathParam("id"));
252	        Reservation reservation = reservationService.checkIn(id);
253	        ctx.json(toResponse(reservation));
254	    }
255	
256	    public void checkOut(Context ctx) {
257	        Long id = parseId(ctx.pathParam("id"));
258	        Reservation reservation = reservationService.checkOut(id);
259	        Room room = roomRepository.findByNumber(reservation.getRoomNumber()).orElseThrow();
260	        ctx.json(toDocumentResponse(reservation, room.getType().name()));
261	    }
262	
263	    public void getDocument(Context ctx) {
264	        Long id = parseId(ctx.pathParam("id"));
265	        Reservation reservation = reservationService.getReservation(id);
266	
267	        if (reservation.getAmountPaid().compareTo(java.math.BigDecimal.ZERO) == 0) {
268	            throw new ApiException(409, "OPERATION_NOT_ALLOWED", "Document is only available for paid reservations");
269	        }
270	
271	        Room room = roomRepository.findByNumber(reservation.getRoomNumber()).orElseThrow();
272	        ctx.json(toDocumentResponse(reservation, room.getType().name()));
273	    }
274	
275	    private void validateRequest(CreateReservationRequest request) {
276	        if (request.roomNumber() == null || request.guestName() == null ||
277	            request.guestEmail() == null || request.guestCpf() == null ||
278	            request.checkIn() == null || request.checkOut() == null ||
279	            request.ratePlan() == null) {
280	            throw new ApiException(400, "INVALID_REQUEST", "Missing required fields");
281	        }
282	    }
