 11	public class NotificationService {
 12	    private static final DateTimeFormatter DATE_FORMAT = DateTimeFormatter.ofPattern("dd/MM/yyyy");
 13	    private static final NumberFormat CURRENCY_FORMAT = NumberFormat.getCurrencyInstance(new Locale("pt", "BR"));
 14	
 15	    private final MessageRepository messageRepository;
 16	
 17	    public NotificationService(MessageRepository messageRepository) {
 18	        this.messageRepository = messageRepository;
 19	    }
 20	
 21	    public void sendConfirmationEmail(Reservation reservation, String roomType) {
 22	        String receipt = formatReceipt(reservation, roomType);
 23	
 24	        String body = String.format("""
 25	            Olá, %s!
 26	
 27	            Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:
 28	
 29	            %s
 30	
 31	            A entrada é a partir das 14h, e a saída, até as 12h.
 32	            Até breve!""", reservation.getGuestName(), receipt);
 33	
 34	        Message message = new Message(
 35	            "EMAIL",
 36	            reservation.getGuestEmail(),
 37	            "Reserva confirmada - Pousada Maré Alta",
 38	            body
 39	        );
 40	
 41	        messageRepository.save(message);
 42	    }
 43	
 44	    public String formatReceipt(Reservation reservation, String roomType) {
 45	        StringBuilder receipt = new StringBuilder();
 46	
 47	        receipt.append(String.format("Comprovante de reserva nº %d\n", reservation.getId()));
 48	        receipt.append(String.format("Hóspede: %s (CPF %s)\n",
 49	            reservation.getGuestName(),
 50	            formatCpf(reservation.getGuestCpf())));
 51	        receipt.append(String.format("Quarto: %s (%s)\n",
 52	            reservation.getRoomNumber(),
 53	            roomType));
 54	        receipt.append(String.format("Entrada: %s | Saída: %s | %d diária%s\n",
 55	            reservation.getCheckIn().format(DATE_FORMAT),
 56	            reservation.getCheckOut().format(DATE_FORMAT),
 57	            reservation.getNights(),
 58	            reservation.getNights() == 1 ? "" : "s"));
 59	        receipt.append(String.format("Diárias: %s\n",
 60	            CURRENCY_FORMAT.format(reservation.getSubtotal())));
 61	
 62	        if (reservation.getDiscount().compareTo(java.math.BigDecimal.ZERO) > 0) {
 63	            receipt.append(String.format("Desconto: %s\n",
 64	                CURRENCY_FORMAT.format(reservation.getDiscount())));
 65	        }
 66	
 67	        receipt.append(String.format("Total: %s",
 68	            CURRENCY_FORMAT.format(reservation.getTotal())));
 69	
 70	        return receipt.toString();
 71	    }
 72	
 73	    private String formatCpf(String cpf) {
 74	        if (cpf.length() == 11) {
 75	            return cpf.substring(0, 3) + "." +
 76	                   cpf.substring(3, 6) + "." +
 77	                   cpf.substring(6, 9) + "-" +
 78	                   cpf.substring(9);
 79	        }
 80	        return cpf;
 81	    }
 82	}
