133	import java.math.BigDecimal;
134	import java.time.LocalDate;
135	import java.time.format.DateTimeFormatter;
136	import java.util.List;
137	
138	public class ReportService {
139	    private static final DateTimeFormatter DATE_FORMAT = DateTimeFormatter.ofPattern("yyyy-MM-dd");
140	
141	    private final ReservationRepository reservationRepository;
142	    private final RoomRepository roomRepository;
143	
144	    public ReportService(ReservationRepository reservationRepository, RoomRepository roomRepository) {
145	        this.reservationRepository = reservationRepository;
146	        this.roomRepository = roomRepository;
147	    }
148	
149	    public String generateOccupancyReport(LocalDate date) {
150	        List<Reservation> reservations = reservationRepository.findByDate(date);
151	        int totalRooms = roomRepository.findAll().size();
152	
153	        StringBuilder csv = new StringBuilder();
154	        csv.append("room,type,reservation,check_in,check_out\n");
155	
156	        for (Reservation reservation : reservations) {
157	            csv.append(String.format("%s,%s,%d,%s,%s\n",
158	                reservation.getRoomNumber(),
159	                getRoomType(reservation.getRoomNumber()),
160	                reservation.getId(),
161	                reservation.getCheckIn().format(DATE_FORMAT),
162	                reservation.getCheckOut().format(DATE_FORMAT)
163	            ));
164	        }
165	
166	        csv.append(String.format("total,%d/%d\n", reservations.size(), totalRooms));
167	
168	        return csv.toString();
169	    }
170	
171	    public String generateRevenueReport(int year, int month) {
172	        List<Reservation> reservations = reservationRepository.findByMonth(year, month);
173	
174	        StringBuilder csv = new StringBuilder();
175	        csv.append("reservation,room,check_in,check_out,status,amount\n");
176	
177	        BigDecimal total = BigDecimal.ZERO;
178	
179	        for (Reservation reservation : reservations) {
180	            BigDecimal amount = calculateRevenue(reservation);
181	            total = total.add(amount);
182	
183	            csv.append(String.format("%d,%s,%s,%s,%s,%s\n",
184	                reservation.getId(),
185	                reservation.getRoomNumber(),
186	                reservation.getCheckIn().format(DATE_FORMAT),
187	                reservation.getCheckOut().format(DATE_FORMAT),
188	                reservation.getStatus().name(),
189	                formatAmount(amount)
190	            ));
191	        }
192	
193	        csv.append(String.format("total,%s\n", formatAmount(total)));
194	
195	        return csv.toString();
196	    }
197	
198	    private BigDecimal calculateRevenue(Reservation reservation) {
199	        BigDecimal revenue = reservation.getAmountPaid();
200	        if (reservation.getRefund() != null) {
201	            revenue = revenue.subtract(reservation.getRefund());
202	        }
