 87	import java.math.BigDecimal;
 88	import java.math.RoundingMode;
 89	import java.time.LocalDate;
 90	import java.time.Month;
 91	
 92	public class PricingService {
 93	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
 94	    private static final RoundingMode ROUNDING_MODE = RoundingMode.HALF_EVEN;
 95	
 96	    public BigDecimal calculateNightlyRate(RoomType roomType, LocalDate date) {
 97	        BigDecimal baseRate = roomType.getNightlyRate();
 98	        if (isHighSeason(date)) {
 99	            return round(baseRate.multiply(HIGH_SEASON_MULTIPLIER));
100	        }
101	        return baseRate;
102	    }
103	
104	    public boolean isHighSeason(LocalDate date) {
105	        Month month = date.getMonth();
106	        int day = date.getDayOfMonth();
107	
108	        if (month == Month.DECEMBER && day >= 15) {
109	            return true;
110	        }
111	
112	        if (month == Month.JANUARY || month == Month.FEBRUARY) {
113	            return true;
114	        }
115	
116	        if (month == Month.JULY) {
117	            return true;
118	        }
119	
120	        return false;
121	    }
122	
123	    public BigDecimal round(BigDecimal value) {
124	        return value.setScale(2, ROUNDING_MODE);
125	    }
126	}
