224	
225	import java.math.BigDecimal;
226	import java.time.temporal.ChronoUnit;
227	import java.util.List;
228	
229	public class ReservationService {
230	    private final ReservationRepository reservationRepository;
231	    private final RoomRepository roomRepository;
232	    private final RatePlanFactory ratePlanFactory;
233	    private final NotificationService notificationService;
234	    private final PricingService pricingService;
235	
236	    public ReservationService(ReservationRepository reservationRepository,
237	                             RoomRepository roomRepository,
238	                             RatePlanFactory ratePlanFactory,
239	                             NotificationService notificationService,
240	                             PricingService pricingService) {
241	        this.reservationRepository = reservationRepository;
242	        this.roomRepository = roomRepository;
243	        this.ratePlanFactory = ratePlanFactory;
244	        this.notificationService = notificationService;
245	        this.pricingService = pricingService;
246	    }
247	
248	    public Reservation createReservation(Reservation reservation) {
249	        Room room = roomRepository.findByNumber(reservation.getRoomNumber())
250	            .orElseThrow(() -> new ApiException(404, "ROOM_NOT_FOUND", "Room not found: " + reservation.getRoomNumber()));
251	
252	        validateReservation(reservation, room);
253	
254	        RatePlanStrategy strategy = ratePlanFactory.getStrategy(reservation.getRatePlan());
255	        strategy.validate(reservation, room);
256	
257	        int nights = (int) ChronoUnit.DAYS.between(reservation.getCheckIn(), reservation.getCheckOut());
258	        reservation.setNights(nights);
259	
260	        BigDecimal subtotal = strategy.calculateSubtotal(reservation, room);
261	        reservation.setSubtotal(subtotal);
262	
263	        BigDecimal discount = strategy.calculateDiscount(subtotal, reservation);
264	        reservation.setDiscount(discount);
265	
266	        BigDecimal total = pricingService.round(subtotal.subtract(discount));
267	        reservation.setTotal(total);
268	
269	        return reservationRepository.save(reservation);
270	    }
271	
272	    private void validateReservation(Reservation reservation, Room room) {
273	        if (reservation.getCheckOut().isBefore(reservation.getCheckIn()) ||
274	            reservation.getCheckOut().equals(reservation.getCheckIn())) {
275	            throw new ApiException(400, "INVALID_REQUEST", "Check-out must be after check-in");
276	        }
277	
278	        if (reservation.getGuests() < 1) {
279	            throw new ApiException(400, "INVALID_REQUEST", "At least one guest is required");
280	        }
281	
282	        if (reservation.getGuests() > room.getCapacity()) {
283	            throw new ApiException(422, "CAPACITY_EXCEEDED",
284	                String.format("Room capacity is %d, requested %d guests", room.getCapacity(), reservation.getGuests()));
285	        }
286	
287	        List<Reservation> conflicts = reservationRepository.findConflicting(
288	            reservation.getRoomNumber(),
289	            reservation.getCheckIn(),
290	            reservation.getCheckOut(),
291	            reservation.getId()
292	        );
293	
294	        if (!conflicts.isEmpty()) {
295	            throw new ApiException(409, "ROOM_UNAVAILABLE", "Room is not available for the selected dates");
296	        }
297	    }
298	
299	    public Reservation getReservation(Long id) {
300	        return reservationRepository.findById(id)
301	            .orElseThrow(() -> new ApiException(404, "RESERVATION_NOT_FOUND", "Reservation not found: " + id));
302	    }
303	
304	    public Reservation confirmReservation(Long id) {
305	        Reservation reservation = getReservation(id);
306	
307	        if (reservation.getStatus() != ReservationStatus.PENDING) {
308	            throw new ApiException(409, "OPERATION_NOT_ALLOWED", "Only pending reservations can be confirmed");
309	        }
310	
311	        reservation.setStatus(ReservationStatus.CONFIRMED);
312	        reservation.setAmountPaid(reservation.getTotal());
313	        reservationRepository.save(reservation);
314	
315	        Room room = roomRepository.findByNumber(reservation.getRoomNumber()).orElseThrow();
316	        notificationService.sendConfirmationEmail(reservation, room.getType().name());
317	
318	        return reservation;
319	    }
320	
321	    public Reservation cancelReservation(Long id) {
322	        Reservation reservation = getReservation(id);
323	
324	        if (reservation.getStatus() != ReservationStatus.PENDING &&
325	            reservation.getStatus() != ReservationStatus.CONFIRMED) {
326	            throw new ApiException(409, "OPERATION_NOT_ALLOWED", "Cannot cancel reservation in current status");
327	        }
328	
329	        reservation.setStatus(ReservationStatus.CANCELLED);
330	
331	        RatePlanStrategy strategy = ratePlanFactory.getStrategy(reservation.getRatePlan());
332	        BigDecimal refundAmount = strategy.calculateRefund(reservation);
333	        reservation.setRefund(pricingService.round(refundAmount));
334	
335	        return reservationRepository.save(reservation);
336	    }
337	
338	    public Reservation checkIn(Long id) {
339	        Reservation reservation = getReservation(id);
340	
341	        if (reservation.getStatus() != ReservationStatus.CONFIRMED) {
342	            throw new ApiException(409, "OPERATION_NOT_ALLOWED", "Only confirmed reservations can be checked in");
343	        }
344	
345	        reservation.setStatus(ReservationStatus.CHECKED_IN);
346	        return reservationRepository.save(reservation);
347	    }
348	
349	    public Reservation checkOut(Long id) {
350	        Reservation reservation = getReservation(id);
351	
352	        if (reservation.getStatus() != ReservationStatus.CHECKED_IN) {
353	            throw new ApiException(409, "OPERATION_NOT_ALLOWED", "Only checked-in reservations can be checked out");
354	        }
355	
356	        reservation.setStatus(ReservationStatus.CHECKED_OUT);
357	        return reservationRepository.save(reservation);
358	    }
359	
360	    public String generateReceipt(Long id) {
361	        Reservation reservation = getReservation(id);
362	
363	        if (reservation.getStatus() == ReservationStatus.PENDING) {
364	            throw new ApiException(409, "OPERATION_NOT_ALLOWED", "Receipt is only available for paid reservations");
365	        }
366	
367	        Room room = roomRepository.findByNumber(reservation.getRoomNumber()).orElseThrow();
368	        return notificationService.formatReceipt(reservation, room.getType().name());
369	    }
370	}
