553	public class StandardRatePlan implements RatePlanStrategy {
554	    private final PricingService pricingService;
555	
556	    public StandardRatePlan(PricingService pricingService) {
557	        this.pricingService = pricingService;
558	    }
559	
560	    @Override
561	    public void validate(Reservation reservation, Room room) {
562	    }
563	
564	    @Override
565	    public BigDecimal calculateSubtotal(Reservation reservation, Room room) {
566	        BigDecimal subtotal = BigDecimal.ZERO;
567	        LocalDate current = reservation.getCheckIn();
568	
569	        while (current.isBefore(reservation.getCheckOut())) {
570	            BigDecimal nightlyRate = pricingService.calculateNightlyRate(room.getType(), current);
571	            subtotal = subtotal.add(nightlyRate);
572	            current = current.plusDays(1);
573	        }
574	
575	        return pricingService.round(subtotal);
576	    }
