616	        long nights = ChronoUnit.DAYS.between(reservation.getCheckIn(), reservation.getCheckOut());
617	        if (nights != 2) {
618	            throw new ApiException(400, "INVALID_REQUEST", "Weekend package requires exactly 2 nights");
619	        }
620	
621	        DayOfWeek checkInDay = reservation.getCheckIn().getDayOfWeek();
622	        DayOfWeek checkOutDay = reservation.getCheckOut().getDayOfWeek();
623	
