456	    private Reservation insert(Reservation reservation) {
457	        String sql = """
458	            INSERT INTO reservations (room_number, guest_name, guest_email, guest_cpf,
459	                check_in, check_out, guests, rate_plan, company_code, nights, subtotal,
460	                discount, total, status, amount_paid, refund)
461	            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
462	            RETURNING id
463	        """;
464	
465	        try (Connection conn = database.getConnection();
466	             PreparedStatement stmt = conn.prepareStatement(sql)) {
467	
468	            setReservationParameters(stmt, reservation);
469	
470	            ResultSet rs = stmt.executeQuery();
471	            if (rs.next()) {
472	                reservation.setId(rs.getLong("id"));
473	            }
474	
475	            return reservation;
476	
477	        } catch (SQLException e) {
478	            throw new RuntimeException("Failed to insert reservation", e);
479	        }
480	    }
481	
482	    private Reservation update(Reservation reservation) {
483	        String sql = """
484	            UPDATE reservations SET room_number = ?, guest_name = ?, guest_email = ?,
485	                guest_cpf = ?, check_in = ?, check_out = ?, guests = ?, rate_plan = ?,
486	                company_code = ?, nights = ?, subtotal = ?, discount = ?, total = ?,
487	                status = ?, amount_paid = ?, refund = ?
488	            WHERE id = ?
489	        """;
490	
491	        try (Connection conn = database.getConnection();
492	             PreparedStatement stmt = conn.prepareStatement(sql)) {
493	
494	            setReservationParameters(stmt, reservation);
495	            stmt.setLong(17, reservation.getId());
496	
497	            stmt.executeUpdate();
498	            return reservation;
499	
500	        } catch (SQLException e) {
501	            throw new RuntimeException("Failed to update reservation", e);
502	        }
503	    }
504	
505	    private void setReservationParameters(PreparedStatement stmt, Reservation reservation) throws SQLException {
506	        stmt.setString(1, reservation.getRoomNumber());
507	        stmt.setString(2, reservation.getGuestName());
508	        stmt.setString(3, reservation.getGuestEmail());
509	        stmt.setString(4, reservation.getGuestCpf());
510	        stmt.setDate(5, Date.valueOf(reservation.getCheckIn()));
511	        stmt.setDate(6, Date.valueOf(reservation.getCheckOut()));
512	        stmt.setInt(7, reservation.getGuests());
513	        stmt.setString(8, reservation.getRatePlan().name());
514	        stmt.setString(9, reservation.getCompanyCode());
515	        stmt.setInt(10, reservation.getNights());
516	        stmt.setBigDecimal(11, reservation.getSubtotal());
517	        stmt.setBigDecimal(12, reservation.getDiscount());
518	        stmt.setBigDecimal(13, reservation.getTotal());
519	        stmt.setString(14, reservation.getStatus().name());
520	        stmt.setBigDecimal(15, reservation.getAmountPaid());
521	
522	        if (reservation.getRefund() != null) {
523	            stmt.setBigDecimal(16, reservation.getRefund());
524	        } else {
525	            stmt.setNull(16, Types.DECIMAL);
526	        }
527	    }
