529	    public Optional<Reservation> findById(Long id) {
530	        String sql = "SELECT * FROM reservations WHERE id = ?";
531	
532	        try (Connection conn = database.getConnection();
533	             PreparedStatement stmt = conn.prepareStatement(sql)) {
534	
535	            stmt.setLong(1, id);
536	            ResultSet rs = stmt.executeQuery();
537	
538	            if (rs.next()) {
539	                return Optional.of(mapReservation(rs));
540	            }
541	            return Optional.empty();
542	
543	        } catch (SQLException e) {
544	            throw new RuntimeException("Failed to find reservation", e);
545	        }
546	    }
