548	    public List<Reservation> findConflicting(String roomNumber, LocalDate checkIn, LocalDate checkOut, Long excludeId) {
549	        String sql = """
550	            SELECT * FROM reservations
551	            WHERE room_number = ?
552	                AND status != 'CANCELLED'
553	                AND check_in < ?
554	                AND check_out > ?
555	                AND id != COALESCE(?, 0)
556	        """;
557	
558	        try (Connection conn = database.getConnection();
559	             PreparedStatement stmt = conn.prepareStatement(sql)) {
560	
561	            stmt.setString(1, roomNumber);
562	            stmt.setDate(2, Date.valueOf(checkOut));
563	            stmt.setDate(3, Date.valueOf(checkIn));
564	            stmt.setLong(4, excludeId != null ? excludeId : 0);
565	
566	            ResultSet rs = stmt.executeQuery();
567	            List<Reservation> reservations = new ArrayList<>();
568	
569	            while (rs.next()) {
570	                reservations.add(mapReservation(rs));
571	            }
572	
573	            return reservations;
574	
575	        } catch (SQLException e) {
576	            throw new RuntimeException("Failed to find conflicting reservations", e);
577	        }
578	    }
579	
580	    public List<Reservation> findByDate(LocalDate date) {
581	        String sql = """
582	            SELECT * FROM reservations
583	            WHERE check_in <= ?
584	                AND check_out > ?
585	                AND status IN ('CONFIRMED', 'CHECKED_IN', 'CHECKED_OUT')
586	            ORDER BY room_number
587	        """;
588	
589	        try (Connection conn = database.getConnection();
590	             PreparedStatement stmt = conn.prepareStatement(sql)) {
591	
592	            stmt.setDate(1, Date.valueOf(date));
593	            stmt.setDate(2, Date.valueOf(date));
594	
595	            ResultSet rs = stmt.executeQuery();
596	            List<Reservation> reservations = new ArrayList<>();
597	
598	            while (rs.next()) {
599	                reservations.add(mapReservation(rs));
600	            }
601	
602	            return reservations;
603	
604	        } catch (SQLException e) {
605	            throw new RuntimeException("Failed to find reservations by date", e);
606	        }
607	    }
608	
609	    public List<Reservation> findByMonth(int year, int month) {
610	        String sql = """
611	            SELECT * FROM reservations
612	            WHERE EXTRACT(YEAR FROM check_in) = ?
613	                AND EXTRACT(MONTH FROM check_in) = ?
614	                AND (amount_paid > 0 OR refund IS NOT NULL)
615	            ORDER BY check_in, id
616	        """;
617	
618	        try (Connection conn = database.getConnection();
619	             PreparedStatement stmt = conn.prepareStatement(sql)) {
620	
621	            stmt.setInt(1, year);
622	            stmt.setInt(2, month);
623	
624	            ResultSet rs = stmt.executeQuery();
625	            List<Reservation> reservations = new ArrayList<>();
626	
627	            while (rs.next()) {
628	                reservations.add(mapReservation(rs));
629	            }
630	
631	            return reservations;
632	
633	        } catch (SQLException e) {
634	            throw new RuntimeException("Failed to find reservations by month", e);
635	        }
636	    }
637	
638	    private Reservation mapReservation(ResultSet rs) throws SQLException {
639	        Reservation reservation = new Reservation();
640	        reservation.setId(rs.getLong("id"));
641	        reservation.setRoomNumber(rs.getString("room_number"));
642	        reservation.setGuestName(rs.getString("guest_name"));
643	        reservation.setGuestEmail(rs.getString("guest_email"));
644	        reservation.setGuestCpf(rs.getString("guest_cpf"));
645	        reservation.setCheckIn(rs.getDate("check_in").toLocalDate());
646	        reservation.setCheckOut(rs.getDate("check_out").toLocalDate());
647	        reservation.setGuests(rs.getInt("guests"));
648	        reservation.setRatePlan(RatePlan.valueOf(rs.getString("rate_plan")));
649	        reservation.setCompanyCode(rs.getString("company_code"));
650	        reservation.setNights(rs.getInt("nights"));
651	        reservation.setSubtotal(rs.getBigDecimal("subtotal"));
652	        reservation.setDiscount(rs.getBigDecimal("discount"));
653	        reservation.setTotal(rs.getBigDecimal("total"));
654	        reservation.setStatus(ReservationStatus.valueOf(rs.getString("status")));
655	        reservation.setAmountPaid(rs.getBigDecimal("amount_paid"));
656	
657	        BigDecimal refund = rs.getBigDecimal("refund");
658	        if (refund != null) {
659	            reservation.setRefund(refund);
660	        }
661	
662	        return reservation;
663	    }
664	}
